(() => {
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clamp=(v,min=0,max=100)=>Math.max(min,Math.min(max,Number(v)||0));
  const fmt=value=>Number(value||0).toLocaleString();
  const icon=name=>BeastAssets.icon(name);
  const empty=text=>`<div class="phase8-empty">${esc(text)}</div>`;
  const statusClass=value=>/fail|critical|block|offline|error/i.test(String(value))?'bad':/warn|degrad|pause|pending/i.test(String(value))?'warn':'ok';
  const panelHead=(title,sub='',tail='')=>`<header class="phase8-panel-head"><div><h3>${esc(title)}</h3>${sub?`<span>${esc(sub)}</span>`:''}</div>${tail}</header>`;
  const metric=(name,value,sub,ico,tone='green')=>`<article class="beast-card compact p8-metric tone-${tone}"><img src="${icon(ico)}" alt=""><div><h3>${esc(name)}</h3><strong>${esc(value)}</strong><span>${esc(sub)}</span></div></article>`;
  const ring=(value,label)=>`<div class="p8-ring" style="--p8-value:${clamp(value)}"><strong>${Math.round(clamp(value))}%</strong><span>${esc(label)}</span></div>`;
  const button=(action,label,ico='tools',kind='secondary')=>`<button class="beast-button ${kind}" data-p8-action="${esc(action)}"><img src="${icon(ico)}" alt="">${esc(label)}</button>`;

  function providerTemplate(){const root=document.createElement('div');root.className='beast-page beast-providers-page';root.innerHTML=`
    <header class="beast-page-head"><div><h2>Provider Plane</h2><div class="sub">LOCAL-FIRST ROUTING // PROVIDER ECONOMIST // FALLBACK CONTROL // CACHE + COMPRESSION</div></div><div class="beast-page-actions">${button('provider-smoke','Run Route Diagnostic','diagnostics')}${button('provider-refresh','Refresh Plane','providers','hot')}</div></header>
    <section class="p8-metric-grid" data-provider-metrics></section>
    <div class="p8-provider-grid">
      <section class="beast-card p8-provider-list">${panelHead('Provider Registry','Governed inference routes','<span class="beast-pill live" data-provider-count>0 ROUTES</span>')}<div class="p8-search-row"><input data-provider-search placeholder="Filter providers or models..."><select data-provider-filter><option value="all">All routes</option><option value="local">Local</option><option value="cloud">Cloud</option></select></div><div data-provider-list></div></section>
      <section class="beast-card p8-route-stage is-active">${panelHead('Inference Cascade','Classification and fallback ladder','<span class="beast-pill" data-provider-policy>LOCAL FIRST</span>')}<div class="p8-route-visual"><div class="p8-route-node source"><img src="${icon('terminal')}" alt=""><b>Operator Request</b><small>task classified</small></div><i></i><div class="p8-route-node governor"><img src="${icon('route')}" alt=""><b>Route Governor</b><small data-provider-winner>selecting...</small></div><i></i><div class="p8-route-stack" data-provider-route-stack></div></div><div class="p8-policy-strip" data-provider-rules></div></section>
      <section class="beast-card p8-provider-inspector">${panelHead('Selected Provider','Capabilities and route contract','<span class="beast-pill" data-provider-selected-state>CHECKING</span>')}<div data-provider-inspector></div><div class="p8-action-stack">${button('provider-select','Set Active Route','target-lock','hot')}${button('provider-compression','Toggle Compression','compute')}${button('provider-cache','Clear KV Cache','memory')}</div></section>
    </div>
    <section class="beast-card p8-trials">${panelHead('Route Trials','Observed quality, latency and governed cost')}<div data-provider-trials></div></section>`;return root;}

  function providersRenderer(){const root=providerTemplate();let disposed=false,query='',filter='all';function patch(state){if(disposed)return;const p=state.providers;root.querySelector('[data-provider-count]').textContent=`${p.registry.length} ROUTES`;root.querySelector('[data-provider-policy]').textContent=String(p.policy||'Local First').toUpperCase();root.querySelector('[data-provider-winner]').textContent=p.economist?.winner||p.activeId||'selecting';root.querySelector('[data-provider-metrics]').innerHTML=[metric('Active Route',p.activeId||'none',p.provider||'governed','route'),metric('Compression',p.compression?'ARMED':'OFF',p.compression?'context economy active':'full context','compute'),metric('KV Cache',p.kvCache?'READY':'OFF',p.runtime?.uptime||'runtime','memory'),metric('Cloud Gate',p.cloudAllowed?'OPEN':'LOCKED',p.policy||'Local First','trust'),metric('Economist',p.economist?.saving||'governed',p.economist?.reason||'route analysis','economy')].join('');
      const rows=p.registry.filter(row=>{const text=`${row.label} ${row.id} ${row.kind}`.toLowerCase();return(!query||text.includes(query))&&(filter==='all'||(filter==='local'&&/local|ollama/i.test(text))||(filter==='cloud'&&!/local|ollama/i.test(text)));});
      root.querySelector('[data-provider-list]').innerHTML=rows.length?rows.map(row=>`<button class="p8-provider-row ${row.id===p.selectedId?'selected':''}" data-provider-id="${esc(row.id)}"><img src="${icon(/local|ollama/i.test(`${row.id} ${row.kind}`)?'model-cube':'providers')}" alt=""><span><b>${esc(row.label)}</b><small>${esc(row.kind)} · ${esc(row.status)}</small></span><em>${esc(row.route||'candidate')}</em><strong>${Math.round(row.confidence||0)}%</strong></button>`).join(''):empty('No providers match this filter.');
      const selected=p.registry.find(row=>row.id===p.selectedId)||p.registry[0]||{};root.querySelector('[data-provider-selected-state]').textContent=String(selected.status||'unknown').toUpperCase();root.querySelector('[data-provider-selected-state]').className=`beast-pill ${statusClass(selected.status)==='ok'?'live':statusClass(selected.status)==='bad'?'bad':'warn'}`;
      root.querySelector('[data-provider-inspector]').innerHTML=`<div class="p8-inspector-hero"><img src="${icon(/local|ollama/i.test(`${selected.id} ${selected.kind}`)?'model-cube':'providers')}" alt=""><div><strong>${esc(selected.label||'No provider')}</strong><span>${esc(selected.id||'unresolved')}</span></div></div><div class="p8-facts"><div><span>Route</span><b>${esc(selected.route||'candidate')}</b></div><div><span>Models</span><b>${esc(selected.models||0)}</b></div><div><span>Latency</span><b>${esc(selected.latency||'n/a')}</b></div><div><span>Cost</span><b>${esc(selected.cost||'governed')}</b></div><div><span>Confidence</span><b>${Math.round(selected.confidence||0)}%</b></div><div><span>Runtime</span><b>${esc(p.runtime?.status||'checking')}</b></div></div>`;
      root.querySelector('[data-provider-route-stack]').innerHTML=p.registry.slice(0,3).map((row,index)=>`<button data-provider-id="${esc(row.id)}" class="${row.id===p.activeId?'active':''}"><img src="${icon(index===0?'model-cube':index===1?'providers':'trust')}" alt=""><span><b>${index===0?'Primary Model':index===1?'Fallback Route':'Escalation Gate'}</b><small>${esc(row.label)}</small></span><em>${row.id===p.activeId?'ACTIVE':String(row.status||'STANDBY').toUpperCase()}</em></button>`).join('');
      root.querySelector('[data-provider-rules]').innerHTML=[['Prefer local','smallest capable route'],['Auto fallback','on error or timeout'],['Context fit','reject insufficient window'],['Cost guard','governed escalation']].map(([a,b])=>`<div><b>✓ ${a}</b><span>${b}</span></div>`).join('');
      root.querySelector('[data-provider-trials]').innerHTML=p.routeTrials.length?p.routeTrials.map(row=>`<div class="p8-trial-row"><span>${esc(row.provider)}</span><div><i style="width:${clamp(row.quality)}%"></i></div><b>${Math.round(row.quality||0)}%</b><small>${esc(row.latency)}ms</small><em>${row.cost===0?'LOCAL':esc(row.cost)}</em></div>`).join(''):empty('Run provider diagnostics to populate route trials.');}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('input',e=>{if(e.target.matches('[data-provider-search]')){query=e.target.value.toLowerCase();patch(BeastStore.get());}});root.addEventListener('change',e=>{if(e.target.matches('[data-provider-filter]')){filter=e.target.value;patch(BeastStore.get());}});root.addEventListener('click',async e=>{try{const row=e.target.closest('[data-provider-id]');if(row){BeastStore.patch('providers',{selectedId:row.dataset.providerId});return;}const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(!action)return;if(action==='provider-refresh')await BeastUtilityOrchestrationBridge.refreshProviders();if(action==='provider-select')await BeastUtilityOrchestrationBridge.selectProvider(BeastStore.get().providers.selectedId);if(action==='provider-smoke')await BeastUtilityOrchestrationBridge.providerAction('smoke');if(action==='provider-compression')await BeastUtilityOrchestrationBridge.providerAction('compression');if(action==='provider-cache')await BeastUtilityOrchestrationBridge.providerAction('cache-clear');}catch(error){BeastStore.patch('providers',{error:String(error.message||error)});document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:`Provider action failed · ${String(error.message||error)}`,tone:'error'}}));}});if(!BeastStore.get().providers.registry.length)BeastUtilityOrchestrationBridge.refreshProviders();return{node:root,dispose(){disposed=true;unsub();}};}

  function systemTemplate(){
    const root=document.createElement('div');
    root.className='beast-page beast-system-page';
    root.innerHTML=`
      <header class="beast-page-head">
        <div>
          <h2>System Plane</h2>
          <div class="sub">RUNTIME GOVERNOR // PREC LIFECYCLE // PLATFORM ATLAS // MEMORY // VECTORS // SWARM</div>
        </div>
        <div class="beast-page-actions">${button('system-sweep','Runtime Sweep','diagnostics')}${button('system-refresh','Refresh System','system','hot')}</div>
      </header>
      <section class="p8-metric-grid" data-system-metrics></section>
      <div class="p8-system-grid">
        <section class="beast-card p8-system-health">${panelHead('System Health','Local runtime posture','<span class="beast-pill" data-system-status>CHECKING</span>')}<div class="p8-health-core"><div data-system-ring></div><div class="p8-bars" data-system-bars></div></div></section>
        <section class="beast-card p8-prec-panel is-active">${panelHead('PREC Lifecycle','Prevent · Review · Evidence · Crystallize','<span class="beast-pill live" data-prec-stage>DISCOVER</span>')}<div class="p8-prec-track" data-prec-track></div><div class="p8-facts" data-prec-facts></div></section>
      </div>
      <section class="beast-card wide is-active">
        ${panelHead('Platform Atlas','Subsystems and integration checkpoints','<span class="beast-pill" data-platform-state>CHECKING</span>')}
        <div class="p8-metric-grid" data-platform-metrics></div>
        <div class="p8-metric-grid" data-platform-sections></div>
      </section>
      <section class="beast-card wide is-active">
        ${panelHead('Control Plane','Direct entry points for the atlas layers and swarm tools','<span class="beast-pill live">VISIBLE UX</span>')}
        <div class="p8-control-plane-grid" data-control-plane></div>
      </section>
      <div class="p8-system-lower">
        <section class="beast-card">${panelHead('Listening Ports','Bound services and collision risk')}<div class="p8-table" data-system-ports></div></section>
        <section class="beast-card">${panelHead('Process Inventory','Runtime ownership and resource use')}<div class="p8-table" data-system-processes></div></section>
        <section class="beast-card">${panelHead('Environment','Resolved platform contract')}<div class="p8-env-grid" data-system-env></div></section>
      </div>`;
    return root;
  }
  function systemRenderer(){
    const root=systemTemplate();
    let disposed=false;
    function sectionActions(section){
      const actions={
        pipeline:[button('sourceplan','Open SourcePlan','source'),button('chronicle','Open Chronicle','chronicle')],
        memory:[button('memory','Open Memory','memory'),button('evidence','Open Evidence','evidence')],
        capabilities:[button('agents','Open Agents','agents'),button('providers','Open Providers','providers')],
        vectors:[button('memory','Open Memory','memory'),button('providers','Open Providers','providers')],
        swarm:[button('agents','Open Swarm','agents','hot'),button('chronicle','Open Chronicle','chronicle')],
        sensorium:[button('doctor','Open Doctor','doctor'),button('chronicle','Open Chronicle','chronicle')],
        tools:[button('tooling','Open Tooling','tools'),button('doctor','Open Doctor','doctor')]
      };
      return `<div class="p8-section-actions">${(actions[section.id] || [button('system','Open System','system')]).join('')}</div>`;
    }
    function renderPlatformSection(section){
      const metrics=(section.metrics||[]).map(item=>{
        const label=Array.isArray(item)?item[0]:item.label;
        const value=Array.isArray(item)?item[1]:item.value;
        const detail=Array.isArray(item)?item[2]:item.detail;
        return `<div><span>${esc(label)}</span><b>${esc(value)}</b><small>${esc(detail||'')}</small></div>`;
      }).join('');
      const tone=statusClass(section.status)==='ok'?'live':statusClass(section.status)==='bad'?'bad':'warn';
      return `<article class="beast-card compact p8-platform-card"><header class="beast-panel-head"><div><h3>${esc(section.title)}</h3><span>${esc(section.summary||'')}</span></div><span class="beast-pill ${tone}">${esc(String(section.status||'checking').toUpperCase())}</span></header><div class="p8-facts">${metrics}</div>${sectionActions(section)}</article>`;
    }
    function patch(state){
      if(disposed)return;
      const s=state.system;
      const platform=state.platform||{};
      const platformSections=Array.isArray(platform.sections)?platform.sections:[];
      const hostCaps=s.hostEnforcement?.capabilities||[];const hostReady=hostCaps.filter(item=>item.available).length;
      root.querySelector('[data-system-metrics]').innerHTML=[metric('CPU',`${Math.round(s.cpu)}%`,'processor load','diagnostics'),metric('Memory',`${Math.round(s.memory)}%`,'allocated memory','memory'),metric('Disk',`${Math.round(s.disk)}%`,'workspace volume','database'),metric('Network',`${Math.round(s.network)}%`,'local throughput','network'),metric('Host Enforcement',`${hostReady}/${hostCaps.length||5}`,s.hostEnforcement?.authority||'operator gated','trust'),metric('Runtime',s.runtime?.status||'checking',`${s.runtime?.circuits||0} open circuits`,'system')].join('');
      const status=root.querySelector('[data-system-status]');
      status.textContent=String(s.status||'checking').toUpperCase();
      status.className=`beast-pill ${s.score>80?'live':s.score>60?'warn':'bad'}`;
      const platformStatus=root.querySelector('[data-platform-state]');
      platformStatus.textContent=String(platform.status||'checking').toUpperCase();
      platformStatus.className=`beast-pill ${platform.health>80?'live':platform.health>60?'warn':'bad'}`;
      root.querySelector('[data-system-ring]').innerHTML=ring(s.score,'SYSTEM HEALTH');
      root.querySelector('[data-system-bars]').innerHTML=[['CPU',s.cpu],['MEMORY',s.memory],['DISK',s.disk],['NETWORK',s.network]].map(([l,v])=>`<div><span>${l}</span><i><b style="width:${clamp(v)}%"></b></i><em>${Math.round(v)}%</em></div>`).join('');
      root.querySelector('[data-prec-stage]').textContent=String(s.prec?.stage||'discover').toUpperCase();
      const stages=['Prevent','Review','Evidence','Crystallize','Reintegrate'];
      const current=Math.max(0,stages.findIndex(x=>x.toLowerCase()===String(s.prec?.stage||'').toLowerCase()));
      root.querySelector('[data-prec-track]').innerHTML=stages.map((stage,index)=>`<div class="${index<=current?'active':''}"><span>${String(index+1).padStart(2,'0')}</span><b>${stage}</b></div>`).join('');
      root.querySelector('[data-prec-facts]').innerHTML=`<div><span>Health</span><b>${s.prec?.health||0}%</b></div><div><span>Traces</span><b>${fmt(s.prec?.traces)}</b></div><div><span>Runtime</span><b>${esc(s.runtime?.status||'checking')}</b></div><div><span>Open circuits</span><b>${s.runtime?.circuits||0}</b></div>`;
      root.querySelector('[data-platform-metrics]').innerHTML=[metric('Health',`${Math.round(platform.health||0)}%`,platform.status||'checking','system'),metric('Sections',(platformSections.length||0),'subsystem overlays','route'),metric('Pipeline',platform.summary?.pipeline_status||'unknown',`${platform.summary?.route_cards||0} route cards`,'source'),metric('Memory',platform.summary?.memory_layers||0,'layers','memory')].join('');
      root.querySelector('[data-platform-sections]').innerHTML=platformSections.length?platformSections.map(renderPlatformSection).join(''):empty('Platform snapshot unavailable.');
      root.querySelector('[data-control-plane]').innerHTML=[
        {action:'sourceplan',label:'Task Envelope',detail:'Draft / verify / apply'},
        {action:'sourceplan',label:'Quality Cascade',detail:'Plan score and gates'},
        {action:'sourceplan',label:'Context Packet',detail:'Selected files and buffer'},
        {action:'sourceplan',label:'Forge Scorecard',detail:'Apply readiness and rollout'},
        {action:'chronicle',label:'Insight Compiler',detail:'Ranked evidence and findings'},
        {action:'system',label:'System / Runtime / PREC',detail:'Health, ports, and lifecycle'},
        {action:'memory',label:'Memory Stack',detail:'L0 to L4 recall layers'},
        {action:'providers',label:'Capability Plane',detail:'Exposure, routes, and policy'},
        {action:'providers',label:'Vector Adapters',detail:'RAG and retrieval surfaces'},
        {action:'memory',label:'Skill Tree / Meta-Tools',detail:'Promotions and reusable patterns'},
        {action:'agents',label:'Swarm / Orchestration',detail:'Mission lanes and agent stack'},
        {action:'chronicle',label:'Sensorium / Interception',detail:'Stream sensing and event mesh'},
        {action:'chronicle',label:'Chronicle / Tool-Laziness',detail:'Learned route skips and history'},
        {action:'memory',label:'Forensic Memory',detail:'Append-only residue and archive'}
      ].map(item=>`<button class="p8-control-card" data-p8-action="${item.action}"><img src="${icon(item.action==='memory'?'memory':item.action==='providers'?'providers':item.action==='agents'?'agents':item.action==='chronicle'?'chronicle':'system')}" alt=""><span><b>${esc(item.label)}</b><small>${esc(item.detail)}</small></span><em>OPEN</em></button>`).join('');
      root.querySelector('[data-system-ports]').innerHTML=s.ports.length?s.ports.map(row=>`<div><img src="${icon('network')}" alt=""><span><b>${esc(row.service)}</b><small>${esc(row.address)}:${esc(row.port)} · PID ${esc(row.pid??'n/a')}</small></span><em class="${statusClass(row.status)}">${esc(row.status)}</em><button data-free-port="${esc(row.port)}">PREVIEW RELEASE</button></div>`).join(''):empty('No listening ports reported.');
      root.querySelector('[data-system-processes]').innerHTML=s.processes.length?s.processes.map(row=>`<div><img src="${icon('system')}" alt=""><span><b>${esc(row.name)}</b><small>PID ${esc(row.pid)} · ${esc(row.memory)}</small></span><em>${esc(row.cpu)}% CPU</em><button data-kill-pid="${esc(row.pid)}">PREVIEW STOP</button></div>`).join(''):empty('No processes reported.');
      root.querySelector('[data-system-env]').innerHTML=s.environment.length?s.environment.map(row=>`<div><span>${esc(Array.isArray(row)?row[0]:row.label||row.name)}</span><b>${esc(Array.isArray(row)?row[1]:row.value||row.version||row.status)}</b></div>`).join(''):empty('Environment contract unresolved.');
    }
    const unsub=BeastStore.subscribe(patch);
    root.addEventListener('click',async e=>{try{
      const port=e.target.closest('[data-free-port]');
      if(port){const value=port.dataset.freePort;const preview=await BeastUtilityOrchestrationBridge.previewSystemAction('free-port',{port:value});const owners=(preview.results||[]).map(item=>item.process?.name||item.process?.cmdline||`PID ${item.pid}`).join(', ')||'the listener';if(confirm(`Release port ${value}? This will send TERM to ${owners}.`))return BeastUtilityOrchestrationBridge.systemAction('free-port',{port:value,approved:true});return;}
      const pid=e.target.closest('[data-kill-pid]');
      if(pid){const value=pid.dataset.killPid;const preview=await BeastUtilityOrchestrationBridge.previewSystemAction('kill',{pid:value});const target=preview.process?.name||preview.process?.cmdline||`process ${value}`;if(confirm(`Stop ${target} (PID ${value})?`))return BeastUtilityOrchestrationBridge.systemAction('kill',{pid:value,approved:true});return;}
      const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;
      if(action==='sourceplan')return BeastRouter.navigate('source');
      if(action==='chronicle')return BeastRouter.navigate('chronicle');
      if(action==='memory')return BeastRouter.navigate('memory');
      if(action==='evidence')return BeastRouter.navigate('evidence');
      if(action==='providers')return BeastRouter.navigate('providers');
      if(action==='agents')return BeastRouter.navigate('agents');
      if(action==='doctor')return BeastRouter.navigate('doctor');
      if(action==='tooling')return BeastRouter.navigate('tooling');
      if(action==='system')return BeastRouter.navigate('system');
      if(action==='system-refresh')await BeastUtilityOrchestrationBridge.refreshPlatform();
      if(action==='system-sweep')await BeastUtilityOrchestrationBridge.systemAction('sweep');
    }catch(error){BeastStore.patch('system',{error:String(error.message||error)});document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:`System action failed · ${String(error.message||error)}`,tone:'error'}}));}});
    if(!BeastStore.get().system.updatedAt)BeastUtilityOrchestrationBridge.refreshPlatform();
    return{node:root,dispose(){disposed=true;unsub();}};
  }

  function settingsTemplate(){const root=document.createElement('div');root.className='beast-page beast-settings-page';root.innerHTML=`<header class="beast-page-head"><div><h2>IDE Controls</h2><div class="sub">TYPOGRAPHY // DENSITY // ATMOSPHERE // MOTION // GOVERNANCE // ACCESSIBILITY</div></div><div class="beast-page-actions">${button('settings-reset','Reset Defaults','settings')}${button('settings-save','Apply Controls','trust','hot')}</div></header><div class="p8-settings-grid"><section class="beast-card is-active">${panelHead('Visual Command','Readable at 100% zoom')}<label class="p8-setting"><span>Typography scale<small>Applies to responsive IDE surfaces</small></span><input type="range" min="0.9" max="1.25" step="0.05" data-setting="typeScale"><b data-setting-output="typeScale"></b></label><label class="p8-setting"><span>Interface density<small>Spacing and operational row height</small></span><select data-setting="density"><option value="compact">Compact</option><option value="comfortable">Comfortable</option><option value="spacious">Spacious</option></select></label><label class="p8-setting"><span>Motion language<small>Living signals and state animation</small></span><select data-setting="motion"><option value="restrained">Restrained</option><option value="balanced">Balanced</option><option value="cinematic">Cinematic</option></select></label><label class="p8-setting"><span>Atmosphere<small>Background contrast and hacker ambience</small></span><select data-setting="atmosphere"><option value="matrix-grid">Matrix rain + grid</option><option value="grid">Grid only</option><option value="matrix">Matrix rain only</option><option value="quiet">Quiet black</option></select></label></section><section class="beast-card">${panelHead('Sensory Layer','Audio and illumination')}<div data-setting-toggles="sensory"></div></section><section class="beast-card">${panelHead('Governance Defaults','Root-cause prevention')}<div data-setting-toggles="governance"></div></section><section class="beast-card p8-setting-preview">${panelHead('Live Preview','Neutral chrome · living signal')}<div class="p8-preview-panel"><img src="${icon('studio')}" alt=""><div><h3>BEAST SIGNAL</h3><p>Readable operational copy with controlled neon emphasis.</p>${button('settings-preview','Preview Active Settings','studio','hot')}</div></div><div class="p8-contrast-row"><i></i><i></i><i></i><i></i><i></i></div></section></div>`;return root;}
  function settingsRenderer(){const root=settingsTemplate();let disposed=false,draft={...BeastStore.get().settings};function toggle(key,label,detail){return`<button class="p8-toggle ${draft[key]?'on':''}" data-toggle-setting="${key}"><span><b>${label}</b><small>${detail}</small></span><i></i></button>`;}function patch(state){if(disposed)return;draft={...draft,...state.settings};root.querySelector('[data-setting="typeScale"]').value=draft.typeScale;root.querySelector('[data-setting-output="typeScale"]').textContent=`${Math.round(draft.typeScale*100)}%`;['density','motion','atmosphere'].forEach(k=>root.querySelector(`[data-setting="${k}"]`).value=draft[k]);root.querySelector('[data-setting-toggles="sensory"]').innerHTML=[toggle('audio','BEAST Audio','Boot, completion and warning identity'),toggle('reducedGlow','Reduced glow','Lower bloom while retaining active signals'),toggle('autoRefresh','Live refresh','Poll operational surfaces when connected')].join('');root.querySelector('[data-setting-toggles="governance"]').innerHTML=[toggle('commandConfirm','Command confirmation','Require explicit approval for governed mutations'),toggle('sourcePlanRequired','SourcePlan required','Prevent direct unplanned workspace writes'),toggle('evidenceClosure','Evidence closure','Attach receipts to completed operations')].join('');}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('input',e=>{const key=e.target.dataset.setting;if(!key)return;draft[key]=key==='typeScale'?Number(e.target.value):e.target.value;if(key==='typeScale')root.querySelector('[data-setting-output="typeScale"]').textContent=`${Math.round(draft.typeScale*100)}%`;BeastUtilityOrchestrationBridge.updateSettings({[key]:draft[key]});});root.addEventListener('click',e=>{const t=e.target.closest('[data-toggle-setting]');if(t){const key=t.dataset.toggleSetting;draft[key]=!draft[key];BeastUtilityOrchestrationBridge.updateSettings({[key]:draft[key]});return;}const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(action==='settings-save')BeastUtilityOrchestrationBridge.updateSettings(draft);if(action==='settings-reset'){draft={theme:'black-chrome',typeScale:1,density:'comfortable',motion:'balanced',atmosphere:'matrix-grid',audio:true,reducedGlow:false,autoRefresh:true,commandConfirm:true,sourcePlanRequired:true,evidenceClosure:true};BeastUtilityOrchestrationBridge.updateSettings(draft);}if(action==='settings-preview'){BeastUtilityOrchestrationBridge.applySettings(draft);BeastFX.trigger('success',e.target,{size:240});document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:'Active display settings previewed',tone:'ok'}}));}});return{node:root,dispose(){disposed=true;unsub();}};}

  function worktreesTemplate(){const root=document.createElement('div');root.className='beast-page beast-worktrees-page';root.innerHTML=`<header class="beast-page-head"><div><h2>Worktree Missions</h2><div class="sub">ISOLATED CHANGES // AGENT OWNERSHIP // DIFF INSPECTION // TEST GATES // CONTROLLED MERGE</div></div><div class="beast-page-actions">${button('worktree-create','New Mission','worktrees')}${button('worktree-refresh','Refresh Missions','worktrees','hot')}</div></header><section class="p8-metric-grid" data-worktree-metrics></section><div class="p8-worktree-grid"><section class="beast-card p8-worktree-list">${panelHead('Mission Stack','Parallel governed workspaces','<span class="beast-pill live" data-worktree-count>0 ACTIVE</span>')}<div data-worktree-list></div></section><section class="beast-card p8-worktree-inspector is-active">${panelHead('Selected Mission','Isolated branch contract','<span class="beast-pill" data-worktree-state>UNRESOLVED</span>')}<div data-worktree-inspector></div><div class="p8-action-grid">${button('worktree-open','Open in Workspace','workspace','hot')}${button('worktree-test','Run Tests','diagnostics','hot')}${button('worktree-diff','Inspect Diff','review')}${button('worktree-sourceplan','Draft SourcePlan','source')}${button('worktree-close','Close Mission','alerts')}</div></section></div><section class="beast-card p8-worktree-diff">${panelHead('Change Surface','Selected worktree diff and verification receipt')}<pre data-worktree-diff></pre></section>`;return root;}
  function worktreesRenderer(){const root=worktreesTemplate();let disposed=false;function patch(state){if(disposed)return;const w=state.worktrees;const active=w.items.filter(x=>x.status!=='closed').length;root.querySelector('[data-worktree-metrics]').innerHTML=[metric('Missions',w.items.length,'isolated worktrees','worktrees'),metric('Active',active,'parallel tasks','agents'),metric('Changed Files',w.items.reduce((a,x)=>a+Number(x.changes||0),0),'across missions','files'),metric('Tests',w.items.filter(x=>/pass|\d+\/\d+/i.test(String(x.tests))).length,'missions reporting','diagnostics')].join('');root.querySelector('[data-worktree-count]').textContent=`${active} ACTIVE`;root.querySelector('[data-worktree-list]').innerHTML=w.items.length?w.items.map(item=>`<button class="p8-worktree-row ${item.id===w.selectedId?'selected':''}" data-worktree-id="${esc(item.id)}"><img src="${icon('worktrees')}" alt=""><span><b>${esc(item.label)}</b><small>${esc(item.branch)} · ${esc(item.owner)}</small><i><u style="width:${clamp(item.progress)}%"></u></i></span><em>${esc(item.status)}</em><strong>${Math.round(item.progress||0)}%</strong></button>`).join(''):empty(`No worktree missions for ${w.root||'the current workspace'}. Select the workspace that owns the mission, then refresh.`);const item=w.items.find(x=>x.id===w.selectedId)||w.items[0]||{};root.querySelector('[data-worktree-state]').textContent=String(item.status||'unresolved').toUpperCase();root.querySelector('[data-worktree-state]').className=`beast-pill ${statusClass(item.status)==='ok'?'live':statusClass(item.status)==='bad'?'bad':'warn'}`;root.querySelector('[data-worktree-inspector]').innerHTML=`<div class="p8-inspector-hero"><img src="${icon('worktrees')}" alt=""><div><strong>${esc(item.label||'No mission selected')}</strong><span>${esc(item.branch||'unresolved')}</span></div></div><div class="p8-facts"><div><span>Registry root</span><b>${esc(w.root||'unresolved')}</b></div><div><span>Path</span><b>${esc(item.path||'pending')}</b></div><div><span>Owner</span><b>${esc(item.owner||'BEAST')}</b></div><div><span>Progress</span><b>${Math.round(item.progress||0)}%</b></div><div><span>Tests</span><b>${esc(item.tests||'pending')}</b></div><div><span>Changed files</span><b>${item.changes||0}</b></div><div><span>Status</span><b>${esc(item.status||'pending')}</b></div></div>`;root.querySelector('[data-worktree-diff]').textContent=w.diff||'Select Inspect Diff to load the change surface.';}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('click',async e=>{const row=e.target.closest('[data-worktree-id]');if(row)return BeastUtilityOrchestrationBridge.worktreeAction('select',row.dataset.worktreeId);const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(!action)return;const id=BeastStore.get().worktrees.selectedId;const selected=BeastStore.get().worktrees.items.find(item=>item.id===id);if(action==='worktree-refresh')await BeastUtilityOrchestrationBridge.refreshWorktrees();if(action==='worktree-create'){const suggested=BeastStore.get().mission.draftObjective||'Implement governed BEAST capability';const objective=prompt('Worktree mission objective',suggested);if(objective)await BeastUtilityOrchestrationBridge.worktreeAction('create','',{objective});}if(action==='worktree-open'){if(!selected?.path)throw new Error('Select a worktree mission with a valid path first.');BeastDesktopBridge.setRoot(selected.path,{preserveWorktreeRegistry:true});await BeastDesktopBridge.listFiles();await BeastRouter.navigate('workspace');}if(action==='worktree-test')await BeastUtilityOrchestrationBridge.worktreeAction('test',id);if(action==='worktree-diff')await BeastUtilityOrchestrationBridge.worktreeAction('diff',id);if(action==='worktree-sourceplan')await BeastUtilityOrchestrationBridge.worktreeAction('sourceplan',id);if(action==='worktree-close'&&confirm('Close selected worktree mission?'))await BeastUtilityOrchestrationBridge.worktreeAction('close',id);});if(!BeastStore.get().worktrees.items.length)BeastUtilityOrchestrationBridge.refreshWorktrees();return{node:root,dispose(){disposed=true;unsub();}};}

  function deployTemplate(){const root=document.createElement('div');root.className='beast-page beast-deploy-page';root.innerHTML=`<header class="beast-page-head"><div><h2>Release Forge</h2><div class="sub">READINESS // RUNBOOK // PORT CONTRACT // ROLLBACK // MANIFEST // VERIFIED RELEASE</div></div><div class="beast-page-actions">${button('deploy-export','Export Runbook','evidence')}${button('deploy-check','Run Readiness','deploy','hot')}</div></header><div class="p8-deploy-hero"><section class="beast-card p8-readiness is-active">${panelHead('Release Readiness','Verified operational delivery','<span class="beast-pill" data-deploy-status>NOT CHECKED</span>')}<div data-deploy-ring></div><div data-deploy-blockers></div></section><section class="beast-card p8-pipeline">${panelHead('Deployment Pipeline','Build to immutable release')}<div class="p8-pipeline-track" data-deploy-stages></div><div class="p8-action-grid">${button('deploy-verify','Verify Runbook','trust','hot')}${button('deploy-open-terminal','Open Terminal','terminal')}</div></section></div><div class="p8-deploy-lower"><section class="beast-card">${panelHead('Release Manifest','Artifacts and rollback contract')}<div class="p8-facts" data-deploy-manifest></div></section><section class="beast-card">${panelHead('Port Readiness','Collision and binding analysis')}<div class="p8-table" data-deploy-ports></div></section><section class="beast-card">${panelHead('Runbook Receipt','Export and verification result')}<pre data-deploy-runbook></pre></section></div>`;return root;}
  function deployRenderer(){const root=deployTemplate();let disposed=false;function patch(state){if(disposed)return;const d=state.deploy;const status=root.querySelector('[data-deploy-status]');status.textContent=String(d.status||'not checked').toUpperCase();status.className=`beast-pill ${d.score>85?'live':d.score>65?'warn':'bad'}`;root.querySelector('[data-deploy-ring]').innerHTML=ring(d.score,'RELEASE SCORE');root.querySelector('[data-deploy-blockers]').innerHTML=d.blockers.length?d.blockers.map(row=>`<div class="p8-blocker ${statusClass(row.severity)}"><img src="${icon(row.severity==='critical'?'alerts':'diagnostics')}" alt=""><span>${esc(row.label)}</span></div>`).join(''):'<div class="p8-blocker ok"><img src="'+icon('trust')+'" alt=""><span>No critical blockers detected.</span></div>';root.querySelector('[data-deploy-stages]').innerHTML=d.stages.length?d.stages.map((stage,index)=>`<div class="${statusClass(stage.status)}"><span>${String(index+1).padStart(2,'0')}</span><img src="${icon(index===0?'workspace':index===1?'diagnostics':index===2?'trust':index===3?'evidence':index===4?'network':'deploy')}" alt=""><b>${esc(stage.label)}</b><em>${esc(stage.status)}</em></div>`).join(''):empty('Run readiness to populate deployment stages.');root.querySelector('[data-deploy-manifest]').innerHTML=Object.keys(d.manifest||{}).length?Object.entries(d.manifest).map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><b>${esc(typeof v==='object'?JSON.stringify(v):v)}</b></div>`).join(''):empty('No release manifest yet.');root.querySelector('[data-deploy-ports]').innerHTML=d.ports.length?d.ports.slice(0,12).map(row=>`<div><img src="${icon('network')}" alt=""><span><b>${esc(row.service||row.name||'service')}</b><small>${esc(row.address||'127.0.0.1')}:${esc(row.port)}</small></span><em class="${statusClass(row.status)}">${esc(row.status||'unknown')}</em></div>`).join(''):empty('No port contract available.');root.querySelector('[data-deploy-runbook]').textContent=d.lastRunbook?JSON.stringify(d.lastRunbook,null,2):'Runbook not exported.';}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('click',async e=>{const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(action==='deploy-check')await BeastUtilityOrchestrationBridge.deployAction('check');if(action==='deploy-export')await BeastUtilityOrchestrationBridge.deployAction('export');if(action==='deploy-verify')await BeastUtilityOrchestrationBridge.deployAction('verify');if(action==='deploy-open-terminal')BeastRouter.navigate('terminal');});if(!BeastStore.get().deploy.updatedAt)BeastUtilityOrchestrationBridge.refreshDeploy();return{node:root,dispose(){disposed=true;unsub();}};}

  function chronicleTemplate(){const root=document.createElement('div');root.className='beast-page beast-chronicle-page';root.innerHTML=`<header class="beast-page-head"><div><h2>Chronicle</h2><div class="sub">EVENT LEDGER // GOVERNANCE RECEIPTS // OPERATIONAL HISTORY // INSIGHT COMPILATION</div></div><div class="beast-page-actions">${button('chronicle-insights','Compile Insights','memory')}${button('chronicle-refresh','Refresh Ledger','chronicle','hot')}</div></header><div class="p8-chronicle-grid"><section class="beast-card p8-chronicle-list">${panelHead('Event Stream','Immutable operational narrative','<span class="beast-pill live" data-chronicle-count>0 EVENTS</span>')}<div class="p8-search-row"><input data-chronicle-query placeholder="Search events, actors or receipts..."><select data-chronicle-filter><option value="all">All events</option><option value="governance">Governance</option><option value="provider">Providers</option><option value="evidence">Evidence</option><option value="runtime">Runtime</option><option value="agent">Agents</option><option value="warning">Warnings</option></select></div><div data-chronicle-events></div></section><section class="beast-card p8-chronicle-detail is-active">${panelHead('Event Inspector','Selected receipt and trace context','<span class="beast-pill" data-chronicle-severity>INFO</span>')}<div data-chronicle-detail></div><div class="p8-insight-stack" data-chronicle-insights></div></section></div><section class="beast-card wide">${panelHead('Sensorium Read Model','Payload-free operational sensing; it does not invent events when the gateway is quiet.','<span class="beast-pill" data-sensorium-status>READ ONLY</span>')}<div class="p8-facts" data-sensorium-facts></div><p class="p8-detail-copy" data-sensorium-copy>Loading the live Sensorium projection…</p></section>`;return root;}
  function chronicleRenderer(){const root=chronicleTemplate();let disposed=false;function patch(state){if(disposed)return;const c=state.chronicle;root.querySelector('[data-chronicle-count]').textContent=`${c.filtered.length} EVENTS`;root.querySelector('[data-chronicle-events]').innerHTML=c.filtered.length?c.filtered.map(row=>`<button class="p8-event-row ${row.id===c.selectedId?'selected':''} ${statusClass(row.severity)}" data-chronicle-id="${esc(row.id)}"><time>${esc(row.time)}</time><img src="${icon(row.kind==='provider'?'providers':row.kind==='evidence'?'evidence':row.kind==='agent'?'agents':row.kind==='runtime'?'system':'chronicle')}" alt=""><span><b>${esc(row.label)}</b><small>${esc(row.actor)} · ${esc(row.kind)}</small></span><em>${esc(row.severity)}</em></button>`).join(''):empty('No events match this query.');const event=c.events.find(x=>x.id===c.selectedId)||c.filtered[0]||{};const sev=root.querySelector('[data-chronicle-severity]');sev.textContent=String(event.severity||'info').toUpperCase();sev.className=`beast-pill ${statusClass(event.severity)==='ok'?'live':statusClass(event.severity)==='bad'?'bad':'warn'}`;root.querySelector('[data-chronicle-detail]').innerHTML=`<div class="p8-inspector-hero"><img src="${icon('chronicle')}" alt=""><div><strong>${esc(event.label||'No event selected')}</strong><span>${esc(event.time||'')} · ${esc(event.actor||'BEAST')}</span></div></div><p class="p8-detail-copy">${esc(event.detail||'Select an event to inspect its receipt.')}</p><div class="p8-facts"><div><span>Event ID</span><b>${esc(event.id||'unresolved')}</b></div><div><span>Category</span><b>${esc(event.kind||'system')}</b></div><div><span>Severity</span><b>${esc(event.severity||'info')}</b></div><div><span>Actor</span><b>${esc(event.actor||'BEAST')}</b></div></div>`;root.querySelector('[data-chronicle-insights]').innerHTML=c.insights.length?c.insights.map((text,index)=>`<article><span>${String(index+1).padStart(2,'0')}</span><p>${esc(text)}</p></article>`).join(''):empty('Compile insights to synthesize the ledger.');const sensor=c.sensorium||{},sequencer=sensor.sequencer||{},episodes=sensor.episodes||{},events=Array.isArray(sensor.recent_events)?sensor.recent_events:[];const sensorStatus=root.querySelector('[data-sensorium-status]');sensorStatus.textContent=String(sensor.authority||'read only').replaceAll('_',' ').toUpperCase();sensorStatus.className=`beast-pill ${events.length?'live':''}`;root.querySelector('[data-sensorium-facts]').innerHTML=[['Published',sequencer.published||0],['Retained',sequencer.retained||0],['Open missions',Object.keys(episodes.open_missions||{}).length],['Closed episodes',episodes.closed_count||0]].map(([label,value])=>`<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('');root.querySelector('[data-sensorium-copy]').textContent=events.length?`${events.length} recent event(s) projected; ${sensor.actuator_available?'actuator available':'read-only observer'}.`:'No Sensorium events have been captured in this gateway session yet. Chronicle remains populated from durable task receipts.';}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('input',e=>{if(e.target.matches('[data-chronicle-query]'))BeastUtilityOrchestrationBridge.filterChronicle({query:e.target.value});});root.addEventListener('change',e=>{if(e.target.matches('[data-chronicle-filter]'))BeastUtilityOrchestrationBridge.filterChronicle({filter:e.target.value});});root.addEventListener('click',async e=>{const row=e.target.closest('[data-chronicle-id]');if(row)return BeastUtilityOrchestrationBridge.selectChronicle(row.dataset.chronicleId);const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(action==='chronicle-refresh')await BeastUtilityOrchestrationBridge.refreshChronicle();if(action==='chronicle-insights')await BeastUtilityOrchestrationBridge.compileInsights();});if(!BeastStore.get().chronicle.events.length)BeastUtilityOrchestrationBridge.refreshChronicle();return{node:root,dispose(){disposed=true;unsub();}};}

  function economyTemplate(){const root=document.createElement('div');root.className='beast-page beast-economy-page';root.innerHTML=`<header class="beast-page-head"><div><h2>Compute Economy</h2><div class="sub">LOCAL-FIRST SAVINGS // VERIFIED REUSE // CONTEXT COMPRESSION // CACHE EFFICIENCY // PROVIDER MIX</div></div><div class="beast-page-actions">${button('economy-refresh','Refresh Economy','economy','hot')}</div></header><section class="p8-metric-grid" data-economy-metrics></section><div class="p8-economy-grid"><section class="beast-card p8-economy-core is-active">${panelHead('Inference Economy Core','Power without waste','<span class="beast-pill live">COMPOUNDING</span>')}<div class="p8-economy-hero"><img src="${icon('economy')}" alt=""><div><strong data-economy-tokens>0</strong><span>VERIFIED TOKENS SAVED</span></div></div><div class="p8-economy-history" data-economy-history></div></section><section class="beast-card">${panelHead('Optimization Stack','Measured efficiency interventions')}<div class="p8-strategy-list" data-economy-strategies></div></section><section class="beast-card">${panelHead('Provider Mix','Where inference resolved')}<div class="p8-provider-mix" data-economy-mix></div></section></div><section class="beast-card p8-economy-principle">${panelHead('Inference Economy Inversion','Probabilistic compute becomes governed, reusable capability')}<div><img src="${icon('crystallization')}" alt=""><p>Every cloud intervention can produce verified, fingerprint-bound residue that compounds into local capability. BEAST measures displacement, reuse and cost avoidance instead of treating inference as disposable exhaust.</p></div></section>`;return root;}
  function economyRenderer(){const root=economyTemplate();let disposed=false;function patch(state){if(disposed)return;const e=state.economy;root.querySelector('[data-economy-metrics]').innerHTML=[metric('Tokens Avoided',fmt(e.tokensSaved),'observed reuse only','economy'),metric('Reuse Events',fmt(e.callsDisplaced),e.reuseRate?`${Math.round(e.reuseRate)}% request-level hit rate`:'no request-level denominator','crystallization'),metric('Compression',`${Math.round(e.compression)}%`,e.compression?'measured context reduction':'enabled; no measured reduction','compute'),metric('Cache Hit',`${Math.round(e.cacheHit)}%`,e.cacheHit?'KV reuse efficiency':'no cache traffic observed','memory'),metric('Cost Avoided',e.costAvoided,'only reported when measured','providers')].join('');root.querySelector('[data-economy-tokens]').textContent=fmt(e.tokensSaved);const history=e.history.length?e.history:[];root.querySelector('[data-economy-history]').innerHTML=history.length?history.map((value,index)=>`<i style="height:${Math.max(8,clamp(value))}%"><span>${index+1}</span></i>`).join(''):`<span class="cortex-empty-list">${esc(e.measurement||'No economy history has been measured yet.')}</span>`;root.querySelector('[data-economy-strategies]').innerHTML=e.strategies.length?e.strategies.map(row=>`<article><img src="${icon(row.label.includes('Crystal')?'crystallization':row.label.toLowerCase().includes('compression')?'compute':row.label.toLowerCase().includes('cache')?'memory':'route')}" alt=""><span><b>${esc(row.label)}</b><small>${esc(row.status)}</small><i><u style="width:${clamp(row.gain)}%"></u></i></span><strong>${Math.round(row.gain||0)}%</strong></article>`).join(''):empty('Economy strategies unresolved.');const total=e.providerMix.reduce((a,x)=>a+Number(x.value||0),0)||1;root.querySelector('[data-economy-mix]').innerHTML=e.providerMix.length?e.providerMix.map(row=>`<article><span><b>${esc(row.label||row.name)}</b><small>${Math.round(Number(row.value||0)/total*100)}%</small></span><i><u style="width:${clamp(Number(row.value||0)/total*100)}%"></u></i></article>`).join(''):empty('No executed provider mix has been measured yet.');}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('click',async e=>{if(e.target.closest('[data-p8-action="economy-refresh"]'))await BeastUtilityOrchestrationBridge.refreshEconomy();});if(!BeastStore.get().economy.updatedAt)BeastUtilityOrchestrationBridge.refreshEconomy();return{node:root,dispose(){disposed=true;unsub();}};}

  function studioTemplate(){const root=document.createElement('div');root.className='beast-page beast-studio-page';root.innerHTML=`<header class="beast-page-head"><div><h2>BEAST Studio</h2><div class="sub">UNIFIED OPERATOR OVERVIEW // PHASE PROGRESS // SYSTEM TOPOLOGY // NEXT BEST ACTION</div></div><div class="beast-page-actions">${button('studio-refresh','Refresh Studio','studio','hot')}</div></header><div class="p8-studio-hero"><section class="beast-card p8-studio-core is-active"><div class="p8-studio-brand"><img src="${icon('studio')}" alt=""><div><span>BEAST CORE SHELL v2</span><h3>Build. Verify. Remember.</h3><p>Governed local-first coding platform with evidence closure and reusable intelligence residue.</p></div></div><div data-studio-health></div></section><section class="beast-card p8-next-action">${panelHead('Next Best Action','Begin a governed coding task','<span class="beast-pill live">AI GOVERNED</span>')}<h3>Define the outcome before you touch the code</h3><p>Start in Mission, plan in a clean chat stream, then create an isolated worktree for implementation.</p>${button('studio-next','Start a Coding Task','mission','hot')}</section></div><section class="p8-metric-grid" data-studio-metrics></section><div class="p8-studio-grid"><section class="beast-card">${panelHead('System Topology','Single-owner page health')}<div class="p8-system-topology" data-studio-systems></div></section><section class="beast-card">${panelHead('Reconstruction Phases','Controlled migration progress')}<div class="p8-phase-stack" data-studio-phases></div></section><section class="beast-card">${panelHead('Quick Launch','Operational surfaces')}<div class="p8-quick-launch" data-studio-actions></div></section></div>`;return root;}
  function studioRenderer(){const root=studioTemplate();let disposed=false;function patch(state){if(disposed)return;const s=state.studio;const total=Math.max(0,Number(s.total)||0),completed=Math.max(0,Number(s.completed)||0);root.querySelector('[data-studio-health]').innerHTML=ring(s.health,'STUDIO HEALTH');root.querySelector('[data-studio-metrics]').innerHTML=[metric('Verified Systems',`${completed}/${total||'?'}`,total?'live contracts observed':'awaiting live contracts','studio'),metric('Systems Online',s.systems.filter(x=>x.ready).length,`${s.systems.length} monitored surfaces`,'system'),metric('Mission Health',`${state.mission.health}%`,state.mission.status,'mission'),metric('Evidence',state.evidence.files.length,`${state.evidence.validity||0}% validity`,'evidence'),metric('Economy',fmt(state.economy.tokensSaved),'tokens saved','economy')].join('');root.querySelector('[data-studio-systems]').innerHTML=s.systems.length?s.systems.map(row=>`<button data-nav="${esc(row.label.toLowerCase().split(' ')[0]==='editor'?'workspace':row.label.toLowerCase().replace('sourceplan','source').replace('crystal','crystallization').replace('provider','providers'))}"><img src="${icon(row.label.includes('Editor')?'workspace':row.label.includes('Source')?'source':row.label.includes('Provider')?'providers':row.label.includes('System')?'system':row.label.toLowerCase().split(' ')[0])}" alt=""><span><b>${esc(row.label)}</b><small>${row.ready?'live contract observed':'checking live contract'}</small></span><i class="${row.ready?'online':''}"></i></button>`).join(''):empty('Studio topology is building.');root.querySelector('[data-studio-phases]').innerHTML=s.systems.length?s.systems.map((system,index)=>`<div class="${system.ready?'complete':''}"><span>${String(index+1).padStart(2,'0')}</span><i></i><b>${esc(system.label)} · ${system.ready?'Verified':'Awaiting evidence'}</b></div>`).join(''):empty('No live subsystem contracts have been observed yet.');root.querySelector('[data-studio-actions]').innerHTML=s.quickActions.map(row=>`<button data-nav="${esc(row.route)}"><img src="${icon(row.route==='deploy'?'deploy':row.route==='economy'?'economy':row.route)}" alt=""><span>${esc(row.label)}</span><em>›</em></button>`).join('');}
    const unsub=BeastStore.subscribe(patch);root.addEventListener('click',async e=>{const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(action==='studio-refresh')await BeastUtilityOrchestrationBridge.refreshStudio();if(action==='studio-next')BeastRouter.navigate('mission');});BeastUtilityOrchestrationBridge.refreshStudio();return{node:root,dispose(){disposed=true;unsub();}};}

  // Studio is subscribed to the entire operational store. Keep its topology
  // and launch controls stable between unrelated telemetry patches; rebuilding
  // them was repeatedly replacing the Systems Atlas icon and caused a visible
  // flicker.
  function studioRenderer(){
    const root=studioTemplate(); let disposed=false;
    let systemsKey='', phasesKey='', actionsKey='', metricsKey='';
    const routeForSystem=label=>({
      'Editor Cortex':'workspace','SourcePlan':'source','Models':'models','Agents':'agents',
      'Review':'review','Evidence':'evidence','Trust':'trust','Memory':'memory','Map':'map',
      'Crystal':'crystallization','Terminal':'terminal','Tooling':'tooling','Doctor':'doctor',
      'Providers':'providers','System':'system','Platform Atlas':'atlas'
    })[label]||'studio';
    const statusCopy=status=>status==='verified'?'Verified':status==='available'?'Available':status==='offline'?'Offline':'Checking';
    function patch(state){
      if(disposed)return; const s=state.studio; const total=Math.max(0,Number(s.total)||0),completed=Math.max(0,Number(s.completed)||0);
      root.querySelector('[data-studio-health]').innerHTML=ring(s.health,'STUDIO HEALTH');
      const nextMetrics=[completed,total,s.systems.filter(x=>x.ready).length,s.systems.length,state.mission.health,state.mission.status,state.evidence.files.length,state.evidence.validity||0,state.economy.tokensSaved];
      const nextMetricsKey=JSON.stringify(nextMetrics);
      if(nextMetricsKey!==metricsKey){metricsKey=nextMetricsKey;root.querySelector('[data-studio-metrics]').innerHTML=[metric('Operational Surfaces',`${completed}/${total||'?'}`,total?'available or live-verified':'gateway unavailable','studio'),metric('Systems Online',s.systems.filter(x=>x.ready).length,`${s.systems.length} monitored surfaces`,'system'),metric('Mission Health',`${state.mission.health}%`,state.mission.status,'mission'),metric('Evidence',state.evidence.files.length,`${state.evidence.validity||0}% validity`,'evidence'),metric('Economy',fmt(state.economy.tokensSaved),'tokens saved','economy')].join('');}
      const nextSystemsKey=JSON.stringify(s.systems.map(row=>[row.label,row.status,row.ready]));
      if(nextSystemsKey!==systemsKey){systemsKey=nextSystemsKey;root.querySelector('[data-studio-systems]').innerHTML=s.systems.length?s.systems.map(row=>`<button data-nav="${esc(routeForSystem(row.label))}"><img src="${icon(row.label.includes('Editor')?'workspace':row.label.includes('Source')?'source':row.label.includes('Provider')?'providers':row.label.includes('System')||row.label==='Platform Atlas'?'system':row.label.toLowerCase().split(' ')[0])}" alt=""><span><b>${esc(row.label)}</b><small>${statusCopy(row.status)} · ${row.status==='verified'?'live contract observed':row.ready?'surface available':'gateway unavailable'}</small></span><i class="${row.ready?'online':''}"></i></button>`).join(''):empty('Studio topology is building.');}
      const nextPhasesKey=nextSystemsKey;
      if(nextPhasesKey!==phasesKey){phasesKey=nextPhasesKey;root.querySelector('[data-studio-phases]').innerHTML=s.systems.length?s.systems.map((system,index)=>`<div class="${system.ready?'complete':''}"><span>${String(index+1).padStart(2,'0')}</span><i></i><b>${esc(system.label)} · ${statusCopy(system.status)}</b></div>`).join(''):empty('No live subsystem contracts have been observed yet.');}
      const nextActionsKey=JSON.stringify(s.quickActions);
      if(nextActionsKey!==actionsKey){actionsKey=nextActionsKey;root.querySelector('[data-studio-actions]').innerHTML=s.quickActions.map(row=>`<button data-nav="${esc(row.route)}"><img src="${icon(row.route==='atlas'?'system':row.route==='deploy'?'deploy':row.route==='economy'?'economy':row.route)}" alt=""><span>${esc(row.label)}</span><em>›</em></button>`).join('');}
    }
    const unsub=BeastStore.subscribe(patch);
    root.addEventListener('click',async e=>{const action=e.target.closest('[data-p8-action]')?.dataset.p8Action;if(action==='studio-refresh')await BeastUtilityOrchestrationBridge.refreshStudio();if(action==='studio-next')BeastRouter.navigate('mission');});
    BeastUtilityOrchestrationBridge.refreshStudio();
    return{node:root,dispose(){disposed=true;unsub();}};
  }

  // Page-local handlers were originally compressed into individual renderers,
  // which let rejected async promises vanish in the browser console.  Capture
  // these high-value operational actions once and always return an operator
  // result (or an actionable failure) to the shared notification surface.
  document.addEventListener('click',async event=>{
    const action=event.target.closest('[data-p8-action]')?.dataset.p8Action;
    if(!['worktree-test','worktree-diff','worktree-sourceplan','worktree-close','deploy-check','deploy-export','deploy-verify','system-refresh'].includes(action))return;
    event.preventDefault();event.stopPropagation();
    try{
      if(action==='system-refresh'){
        await BeastUtilityOrchestrationBridge.refreshPlatform();
        document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:'System snapshot refreshed · runtime, PREC, ports, and Atlas contracts updated',tone:'ok'}}));
      }else if(action.startsWith('worktree-')){
        const id=BeastStore.get().worktrees.selectedId;
        if(!id)throw new Error('Select a worktree mission first. The current workspace registry may not own the mission.');
        const operation=action.replace('worktree-','');
        if(operation==='close'&&!confirm('Close selected worktree mission?'))return;
        await BeastUtilityOrchestrationBridge.worktreeAction(operation,id);
      }else if(action==='deploy-check'){
        await BeastUtilityOrchestrationBridge.deployAction('check');
      }else{
        await BeastUtilityOrchestrationBridge.deployAction(action.replace('deploy-',''));
      }
    }catch(error){
      const message=String(error.message||error);
      BeastStore.patch(action.startsWith('worktree-')?'worktrees':'deploy',{error:message});
      document.dispatchEvent(new CustomEvent('beast:operation',{detail:{message:`${action.replaceAll('-',' ')} failed · ${message}`,tone:'error'}}));
    }
  },true);

  window.BeastProvidersPage={renderer:providersRenderer};
  window.BeastSystemPage={renderer:systemRenderer};
  window.BeastSettingsPage={renderer:settingsRenderer};
  window.BeastWorktreesPage={renderer:worktreesRenderer};
  window.BeastDeployPage={renderer:deployRenderer};
  window.BeastChroniclePage={renderer:chronicleRenderer};
  window.BeastEconomyPage={renderer:economyRenderer};
  window.BeastStudioPage={renderer:studioRenderer};
})();
